  "accordion": "import { Bell, Layers } from \"lucide-react\";\nimport {\n  Accordion,\n  AccordionContent,\n  AccordionItem,\n  AccordionTrigger,\n  Badge,\n  Input,\n} from \"@fabrials/ui\";\n\nexport function AccordionExample() {\n  return (\n    <div className=\"grid gap-4\">\n      <Accordion defaultValue={[\"keys\"]} className=\"max-w-xl\">\n        <AccordionItem value=\"keys\">\n          <AccordionTrigger>Where are keys stored?</AccordionTrigger>\n          <AccordionContent>\n            In the operating system&apos;s secret store, never in the browser.\n          </AccordionContent>\n        </AccordionItem>\n        <AccordionItem value=\"share\">\n          <AccordionTrigger>\n            What does a shared snapshot contain?\n          </AccordionTrigger>\n          <AccordionContent>\n            Daily totals per provider. No prompts, files or account names.\n          </AccordionContent>\n        </AccordionItem>\n      </Accordion>\n      <Accordion\n        variant=\"rows\"\n        multiple\n        defaultValue={[\"reminders\"]}\n        className=\"max-w-xl overflow-hidden rounded-md border\"\n      >\n        <AccordionItem value=\"reminders\">\n          <AccordionTrigger\n            headingLevel={3}\n            icon={<Bell aria-hidden />}\n            aside={\n              <>\n                <Badge tone=\"warning\" dot>\n                  Needs review\n                </Badge>\n                <Badge>3</Badge>\n              </>\n            }\n          >\n            Reminders\n          </AccordionTrigger>\n          <AccordionContent>\n            <Input aria-label=\"Remind me about\" defaultValue=\"Renewal quote\" />\n          </AccordionContent>\n        </AccordionItem>\n        <AccordionItem value=\"labels\">\n          <AccordionTrigger\n            headingLevel={3}\n            icon={<Layers aria-hidden />}\n            aside={<Badge>12</Badge>}\n          >\n            Labels\n          </AccordionTrigger>\n          <AccordionContent>Twelve labels.</AccordionContent>\n        </AccordionItem>\n      </Accordion>\n    </div>\n  );\n}",
  "activity-disclosure": "import { Terminal } from \"lucide-react\";\nimport {\n  ActivityDisclosure,\n  ReasoningDisclosure,\n  SearchStepsDisclosure,\n  type SearchStep,\n} from \"@fabrials/ai-ui\";\n\nconst searchSteps: SearchStep[] = [\n  { type: \"search\", query: \"css cascade layers component libraries\" },\n  { type: \"search\", query: \"color-mix oklab browser support 2026\" },\n  { type: \"open_page\", url: \"https://docs.example.org/guides/cascade-layers\" },\n];\n\nexport function ActivityDisclosureExample() {\n  return (\n    <div className=\"grid gap-4\">\n      <ReasoningDisclosure streaming>\n        <div className=\"fui-markdown\">\n          <p>Comparing the two layer orders before choosing one.</p>\n        </div>\n      </ReasoningDisclosure>\n      <ReasoningDisclosure durationSeconds={4}>\n        <div className=\"fui-markdown\">\n          <p>\n            The host imports tokens first, then shared components, then\n            overrides.\n          </p>\n        </div>\n      </ReasoningDisclosure>\n      <SearchStepsDisclosure\n        phase=\"reading\"\n        sourceCount={5}\n        steps={searchSteps}\n      />\n      <SearchStepsDisclosure\n        defaultOpen\n        phase=\"done\"\n        sourceCount={5}\n        steps={searchSteps}\n      />\n      <ActivityDisclosure\n        icon={<Terminal aria-hidden=\"true\" />}\n        label=\"Ran a calculation\"\n        live={false}\n      />\n    </div>\n  );\n}",
  "activity-strip": "import { ActivityStrip } from \"@fabrials/ui\";\n\nlet seed = 11;\n\nconst random = () => (seed = (seed * 16807) % 2147483647) / 2147483647;\n\nconst days = Array.from({ length: 60 }, (_, i) => ({\n  label: `Day ${i + 1}`,\n  value: Math.round(random() * random() * 14),\n}));\n\nexport function ActivityStripExample() {\n  return (\n    <ActivityStrip\n      caption=\"Posts per day, last 60 days\"\n      cells={days}\n      startLabel=\"60 days ago\"\n      endLabel=\"today\"\n    />\n  );\n}",
  "alert": "import {\n  Alert,\n  AlertAction,\n  AlertDescription,\n  AlertTitle,\n  Button,\n} from \"@fabrials/ui\";\n\nexport function AlertExample() {\n  return (\n    <div className=\"grid gap-4\">\n      <Alert>\n        <AlertTitle>Observation is stale</AlertTitle>\n        <AlertDescription>\n          The last sync is 14 minutes old. Refresh before acting on it.\n        </AlertDescription>\n      </Alert>\n      <Alert layout=\"inline\" variant=\"warning\">\n        <AlertTitle>You are offline</AlertTitle>\n        <AlertDescription>\n          Changes wait for the connection. From 48rem this sits on one line.\n        </AlertDescription>\n        <AlertAction>\n          <Button variant=\"outline\" size=\"sm\">\n            Retry now\n          </Button>\n        </AlertAction>\n      </Alert>\n    </div>\n  );\n}",
