  "auth-layout": "import { AuthLayout, Button, DitherScene, ProductLockup } from \"@fabrials/ui\";\n\nexport function AuthLayoutExample() {\n  return (\n    <div className=\"w-full overflow-hidden rounded-(--fui-radius-lg) border [&_.fui-auth]:min-h-[30rem]\">\n      <AuthLayout\n        brand={<ProductLockup product=\"Fabrials\" gem=\"stormlight\" />}\n        title=\"Sign in\"\n        description=\"One account for fabrials.com, ai.fabrials.com and the admin console.\"\n        aside={<DitherScene variant=\"full\" reveal={0} />}\n        footer=\"We read your X handle and avatar, nothing else.\"\n        actions={\n          <Button variant=\"ghost\" size=\"sm\">\n            English\n          </Button>\n        }\n        headingLevel={2}\n        // The docs page already has its <main>; the layout's default landmark would be a second one.\n        as=\"div\"\n      >\n        <Button>Continue with X</Button>\n      </AuthLayout>\n    </div>\n  );\n}",
  "avatar": "import { Avatar, AvatarFallback, avatarInitials } from \"@fabrials/ui\";\n\nexport function AvatarExample() {\n  return (\n    <div className=\"flex items-center gap-3\">\n      <Avatar size=\"sm\">\n        <AvatarFallback>{avatarInitials(\"Ada Lovelace\")}</AvatarFallback>\n      </Avatar>\n      <Avatar>\n        <AvatarFallback>{avatarInitials(\"nora@example.org\")}</AvatarFallback>\n      </Avatar>\n      <Avatar size=\"lg\">\n        <AvatarFallback>{avatarInitials(\"Paul Kerr Jr\")}</AvatarFallback>\n      </Avatar>\n    </div>\n  );\n}",
  "avatar-group": "import {\n  Avatar,\n  AvatarBadge,\n  AvatarFallback,\n  AvatarGroup,\n  avatarInitials,\n} from \"@fabrials/ui\";\n\nconst PEOPLE = [\n  { id: \"ana\", name: \"Ana Lopez\", role: \"Billing\" },\n  { id: \"kai\", name: \"Kai Nakamura\", role: \"Support\" },\n  { id: \"priya\", name: \"Priya Shah\", role: \"Operations\" },\n  { id: \"tom\", name: \"Tom Adeyemi\", role: \"Engineering\" },\n];\n\nexport function AvatarGroupExample() {\n  return (\n    <div className=\"flex flex-wrap items-center gap-6\">\n      <AvatarGroup max={3}>\n        {PEOPLE.map((person) => (\n          <Avatar key={person.id}>\n            <AvatarFallback>{avatarInitials(person.name)}</AvatarFallback>\n          </Avatar>\n        ))}\n      </AvatarGroup>\n      <Avatar size=\"lg\">\n        <AvatarFallback>KN</AvatarFallback>\n        <AvatarBadge tone=\"success\" label=\"Online\" />\n      </Avatar>\n      <span className=\"text-sm\">Kai Nakamura · Online</span>\n    </div>\n  );\n}",
  "badge": "import { Badge } from \"@fabrials/ui\";\n\nexport function BadgeExample() {\n  return (\n    <div className=\"grid gap-4\">\n      <div className=\"flex flex-wrap gap-2\">\n        <Badge>Draft</Badge>\n        <Badge tone=\"success\">Current</Badge>\n        <Badge tone=\"warning\">Stale</Badge>\n        <Badge tone=\"danger\">Failed</Badge>\n        <Badge tone=\"info\">Preview</Badge>\n      </div>\n      <div className=\"flex flex-wrap gap-2\">\n        <Badge dot tone=\"success\">\n          Synced\n        </Badge>\n        <Badge dot tone=\"warning\">\n          3 h old\n        </Badge>\n        <Badge dot tone=\"danger\">\n          Expired\n        </Badge>\n        <Badge dot>Paused</Badge>\n      </div>\n      <div className=\"flex flex-wrap gap-2\">\n        <Badge variant=\"outline\">MIT</Badge>\n        <Badge variant=\"outline\">v0.11.0</Badge>\n        <Badge variant=\"solid\" tone=\"info\">\n          New\n        </Badge>\n        <Badge variant=\"solid\">12</Badge>\n      </div>\n      <div className=\"flex min-w-0 flex-wrap gap-2\">\n        <Badge dot dotColor=\"var(--chart-2)\">\n          Travel\n        </Badge>\n        <Badge variant=\"outline\" dot=\"hollow\" dotColor=\"var(--chart-2)\">\n          Travel, archived\n        </Badge>\n        <Badge\n          truncate\n          variant=\"outline\"\n          style={{ \"--fui-badge-max\": \"9rem\" } as React.CSSProperties}\n        >\n          A label that is far too long for its row\n        </Badge>\n      </div>\n    </div>\n  );\n}",
  "breadcrumb": "import {\n  Breadcrumb,\n  BreadcrumbItem,\n  BreadcrumbLink,\n  BreadcrumbList,\n  BreadcrumbPage,\n  BreadcrumbSeparator,\n} from \"@fabrials/ui\";\n\nexport function BreadcrumbExample() {\n  return (\n    <Breadcrumb>\n      <BreadcrumbList>\n        <BreadcrumbItem>\n          <BreadcrumbLink href=\"#preview\">Accounts</BreadcrumbLink>\n        </BreadcrumbItem>\n        <BreadcrumbSeparator />\n        <BreadcrumbItem>\n          <BreadcrumbLink href=\"#preview\">Grok</BreadcrumbLink>\n        </BreadcrumbItem>\n        <BreadcrumbSeparator />\n        <BreadcrumbItem>\n          <BreadcrumbPage>Usage</BreadcrumbPage>\n        </BreadcrumbItem>\n      </BreadcrumbList>\n    </Breadcrumb>\n  );\n}",
  "bulk-actions": "import { BulkActions, Button } from \"@fabrials/ui\";\n\nexport function BulkActionsExample() {\n  return (\n    <div className=\"grid gap-4\">\n      <BulkActions count={2}>\n        <Button variant=\"outline\" size=\"sm\">\n          Archive\n        </Button>\n      </BulkActions>\n      <BulkActions count={0} keepMounted>\n        <Button variant=\"outline\" size=\"sm\">\n          Archive\n        </Button>\n      </BulkActions>\n    </div>\n  );\n}",
